findings.patch:
Treat a settings-lookup error as a hard failure, mirroring HandleOpenReport:

required, err := policy.RequiresTwoFactor(report.ProgrammeID)
if err != nil {
    return scyna.NewError(scyna.StatusCodeServerError, "cannot evaluate programme policy")
}
if required && !session.TwoFactorEnabled {
    return scyna.NewError(scyna.StatusCodeForbidden, "this programme requires two-factor authentication")
}
